import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, ListGroup, ListGroupItem } from 'reactstrap';
import ContractModal from './ContractModal';

const ProposalListModal = ({ isOpen, toggle, userId }) => {
    const [proposals, setProposals] = useState([]);
    const [isContractModalOpen, setIsContractModalOpen] = useState(false);

    useEffect(() => {
        if (isOpen && userId) {
            fetch(`http://localhost:8080/api/proposals/byUserId/${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    console.log('Fetched proposals:', data);
                    if (Array.isArray(data)) {
                        setProposals(data);
                    } else {
                        setProposals([]);
                    }
                })
                .catch((error) => {
                    console.error('Error:', error);
                    setProposals([]);
                });
        }
    }, [isOpen, userId]);

    const toggleContractModal = () => setIsContractModalOpen(!isContractModalOpen);
    const refreshProposals = () => {
        if (userId) {
            fetch(`http://localhost:8080/api/proposals/byUserId/${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    console.log('Fetched proposals:', data);
                    if (Array.isArray(data)) {
                        setProposals(data);
                    } else {
                        setProposals([]);
                    }
                })
                .catch((error) => {
                    console.error('Error:', error);
                    setProposals([]);
                });
        }
    };

    return (
        <>
            <Modal isOpen={isOpen} toggle={toggle} size="lg">
                <ModalHeader toggle={toggle}>제안서 목록</ModalHeader>
                <ModalBody>
                    <ListGroup>
                        {proposals.length > 0 ? (
                            proposals.map((proposal) => (
                                <ListGroupItem key={proposal.id}>이름 : {proposal.goodName}</ListGroupItem>
                            ))
                        ) : (
                            <div>제안서가 없습니다.</div>
                        )}
                    </ListGroup>
                </ModalBody>
                <ModalFooter>
                    <Button color="primary" onClick={toggleContractModal}>
                        제안서 생성
                    </Button>
                    <Button color="secondary" onClick={toggle}>
                        닫기
                    </Button>
                </ModalFooter>
            </Modal>

            <ContractModal
                isOpen={isContractModalOpen}
                toggle={toggleContractModal}
                email={userId}
                refreshProposals={refreshProposals}
            />
        </>
    );
};

export default ProposalListModal;
